# This can be solved with backtracking.
def find_max_k_backtrack(n):
    grid = [[0]*n for _ in range(n)]
    max_k = [0]

    def backtrack(r, c, current_k):
        if r == n:
            if current_k > max_k[0]:
                max_k[0] = current_k
            return

        next_r, next_c = (r, c + 1) if c < n - 1 else (r + 1, 0)

        for val in [0, 1]:
            grid[r][c] = val

            # Check if the 2x2 block ending at (r,c) is valid
            if r > 0 and c > 0:
                s = grid[r-1][c-1] + grid[r-1][c] + grid[r][c-1] + grid[r][c]
                if s not in [0, 1, 4]:
                    continue

            # Optimization: if the remaining cells can't beat max_k, prune
            remaining_cells = (n - 1 - r) * n + (n - 1 - c)
            if current_k + val + remaining_cells <= max_k[0]:
                continue

            backtrack(next_r, next_c, current_k + val)

    backtrack(0, 0, 0)
    return max_k[0]

