            remaining_cells = (n - 1 - r) * n + (n - 1 - c)
            if current_k + val + remaining_cells <= max_k[0]:
                continue
            backtrack(next_r, next_c, current_k + val)
    backtrack(0, 0, 0)
    # We want the largest k < n^2.
    if max_k[0] == n*n:
        grid = [[0]*n for _ in range(n)]
        max_k_list = [0, 0]
        def backtrack_second(r, c, current_k):
            if r == n:
                if current_k > max_k_list[0]:
                    max_k_list[1] = max_k_list[0]
                    max_k_list[0] = current_k
                elif current_k > max_k_list[1]:
                    max_k_list[1] = current_k
                return
            next_r, next_c = (r, c + 1) if c < n - 1 else (r + 1, 0)
            for val in [1, 0]:
                grid[r][c] = val
                if r > 0 and c > 0:
