                remaining_cells = (n - 1 - r) * n + (n - 1 - c)
                if current_k + val + remaining_cells <= max_k_list[1]:
                    continue
                backtrack_second(next_r, next_c, current_k + val)
        backtrack_second(0, 0, 0)
        return max_k_list[1]
    else:
        return max_k[0]

