    def backtrack(current_rows):
        nonlocal max_k
        if len(current_rows) == N:
            k = sum(sum(row) for row in current_rows)
            if k < N*N:
                max_k = max(max_k, k)
            return

        for next_row in itertools.product([0, 1], repeat=N):
            valid = True
            prev_row = current_rows[-1]
            for c in range(N-1):
                s = prev_row[c] + prev_row[c+1] + next_row[c] + next_row[c+1]
                if s == 2 or s == 3:
                    valid = False
                    break
            if valid:
                backtrack(current_rows + [next_row])

    for row1 in itertools.product([0, 1], repeat=N):
        backtrack([row1])
    return max_k

