import itertools

def solve():
    # For a 2x2 dish, find the minimum k
    for k in range(1, 5):
        possible = True
        for initial_state in itertools.product([0, 1], repeat=4):
            if sum(initial_state) != k:
                continue

            # BFS to see if we can reach (1,1,1,1)
            queue = [initial_state]
            visited = {initial_state}
            found = False
            while queue:
                curr = queue.pop(0)
                if curr == (1, 1, 1, 1):
                    found = True
                    break

                # Rule 1: 3 -> 4
                # A 2x2 square is just the 4 elements.
                if sum(curr) == 3:
                    new_state = (1, 1, 1, 1)
                    if new_state not in visited:
                        visited.add(new_state)
                        queue.append(new_state)

                # Rule 2: 2 -> 2 (flip all)
                if sum(curr) == 2:
                    new_state = tuple(1 - x for x in curr)
                    if new_state not in visited:
                        visited.add(new_state)
                        queue.append(new_state)

            if not found:
                possible = False
                break

        if possible:
            print(f"2x2: k={k}")
            return

