import itertools

def solve_nxn(n):
    for k in range(1, (n*n)+1):
        possible = True
        # To save time, we only check a few initial states for each k
        # But we need to be sure. Let's check all for small n.
        for initial_state in itertools.product([0, 1], repeat=n*n):
            if sum(initial_state) != k:
                continue

            queue = [initial_state]
            visited = {initial_state}
            found = False
            while queue:
                curr = queue.pop(0)
                if sum(curr) == n*n:
                    found = True
                    break

                # Rule 1: 3 -> 4
                # Rule 2: 2 -> 2 (flip all)
                # Try all 2x2 blocks
                for i in range(n-1):
                    for j in range(n-1):
                        # 2x2 block at (i,j), (i+1,j), (i,j+1), (i+1,j+1)
                        idx = [i*n+j, (i+1)*n+j, i*n+j+1, (i+1)*n+j+1]
                        block_sum = sum(curr[i] for i in idx)

                        if block_sum == 3:
                            # Rule 1
                            new_list = list(curr)
                            for i_idx in idx:
                                if new_list[i_idx] == 0:
                                    new_list[i_idx] = 1
                                    break
                            new_state = tuple(new_list)
                            if new_state not in visited:
                                visited.add(new_state)
                                queue.append(new_state)
                        elif block_sum == 2:
                            # Rule 2
                            new_list = list(curr)
                            for i_idx in idx:
                                new_list[i_idx] = 1 - new_list[i_idx]
                            new_state = tuple(new_list)
                            if new_state not in visited:
                                visited.add(new_state)
                                queue.append(new_state)

            if not found:
                possible = False
                break

        if possible:
            print(f"{n}x{n}: k={k}")
            return

