import itertools

def solve_nxn_efficient(n, k):
    # This will check if all configurations of size k can reach all-1s.
    # Since we want the smallest k, we'll test k = 1, 2, 3...
    # To make it faster, we will return False as soon as we find a configuration that fails.
    for initial_state in itertools.product([0, 1], repeat=n*n):
        if sum(initial_state) != k:
            continue

        queue = [initial_state]
        visited = {initial_state}
        found = False
        while queue:
            curr = queue.pop(0)
            if sum(curr) == n*n:
                found = True
                break

            for i in range(n-1):
                for j in range(n-1):
                    idx = [i*n+j, (i+1)*n+j, i*n+j+1, (i+1)*n+j+1]
                    block_sum = sum(curr[m] for m in idx)

                    if block_sum == 3:
                        new_list = list(curr)
                        for m in idx:
                            if new_list[m] == 0:
                                new_list[m] = 1
                                break
                        new_state = tuple(new_list)
                        if new_state not in visited:
                            visited.add(new_state)
                            queue.append(new_state)
                    elif block_sum == 2:
                        new_list = list(curr)
                        for m in idx:
                            new_list[m] = 1 - new_list[m]
                        new_state = tuple(new_list)
                        if new_state not in visited:
                            visited.add(new_state)
                            queue.append(new_state)

        if not found:
